  scopedRoles: {
    'org:org-1': ['admin'],
    'org:org-2': ['viewer'],
  },
}

engine.can({ subject, action: 'delete', resource: 'post', scope: 'org:org-1' })
// -> true (admin in this org)

engine.can({ subject, action: 'delete', resource: 'post', scope: 'org:org-2' })
